// ============================================
// EntreSkillHub - Main App Component
// Router setup with all routes
// ============================================

import React, { Suspense, lazy } from 'react';
import { Routes, Route } from 'react-router-dom';
import { useAuth } from './context/AuthContext';
import { PageLoader } from './components/common/Loader';
import ProtectedRoute, { PublicOnlyRoute } from './components/auth/ProtectedRoute';

// Lazy load pages
const HomePage = lazy(() => import('./pages/HomePage'));
const LoginPage = lazy(() => import('./pages/LoginPage'));
const RegisterPage = lazy(() => import('./pages/RegisterPage'));
const DashboardPage = lazy(() => import('./pages/DashboardPage'));
const BusinessIdeasPage = lazy(() => import('./pages/BusinessIdeasPage'));
const NotFoundPage = lazy(() => import('./pages/NotFoundPage'));

const ComingSoonPage = ({ title }) => (
  <div className="min-h-screen flex items-center justify-center bg-dark-50 dark:bg-dark-900">
    <div className="text-center">
      <h1 className="text-5xl font-bold gradient-text mb-4">{title}</h1>
      <p className="text-dark-500 text-lg">Coming Soon! 🚀</p>
      <a href="/" className="btn-primary mt-6 inline-flex">
        ← Back to Home
      </a>
    </div>
  </div>
);

function App() {
  const { loading } = useAuth();

  if (loading) {
    return <PageLoader message="Initializing EntreSkillHub..." />;
  }

  return (
    <Suspense fallback={<PageLoader message="Loading page..." />}>
      <Routes>
        {/* Public Routes */}
        <Route path="/" element={<HomePage />} />
        <Route path="/about" element={<ComingSoonPage title="About Us" />} />
        <Route path="/contact" element={<ComingSoonPage title="Contact" />} />

        {/* Business Ideas */}
        <Route path="/business-ideas" element={<BusinessIdeasPage />} />
        <Route path="/business-ideas/:identifier" element={<ComingSoonPage title="Business Idea Details" />} />

        {/* Roadmaps */}
        <Route path="/roadmaps" element={<ComingSoonPage title="Roadmaps" />} />
        <Route path="/roadmaps/:identifier" element={<ComingSoonPage title="Roadmap Details" />} />

        {/* Resources */}
        <Route path="/resources" element={<ComingSoonPage title="Learning Resources" />} />
        <Route path="/resources/:identifier" element={<ComingSoonPage title="Resource Details" />} />

        {/* Mentors */}
        <Route path="/mentors" element={<ComingSoonPage title="Mentors" />} />
        <Route path="/mentors/:identifier" element={<ComingSoonPage title="Mentor Profile" />} />

        {/* Auth Routes */}
        <Route
          path="/login"
          element={
            <PublicOnlyRoute>
              <LoginPage />
            </PublicOnlyRoute>
          }
        />
        <Route
          path="/register"
          element={
            <PublicOnlyRoute>
              <RegisterPage />
            </PublicOnlyRoute>
          }
        />
        <Route path="/forgot-password" element={<ComingSoonPage title="Forgot Password" />} />
        <Route path="/reset-password/:token" element={<ComingSoonPage title="Reset Password" />} />
        <Route path="/verify-email/:token" element={<ComingSoonPage title="Verify Email" />} />

        {/* Protected User Routes */}
        <Route
          path="/dashboard"
          element={
            <ProtectedRoute>
              <DashboardPage />
            </ProtectedRoute>
          }
        />
        <Route
          path="/profile"
          element={
            <ProtectedRoute>
              <ComingSoonPage title="Profile" />
            </ProtectedRoute>
          }
        />
        <Route
          path="/skill-assessment"
          element={
            <ProtectedRoute>
              <ComingSoonPage title="Skill Assessment" />
            </ProtectedRoute>
          }
        />
        <Route
          path="/bookmarks"
          element={
            <ProtectedRoute>
              <ComingSoonPage title="Bookmarks" />
            </ProtectedRoute>
          }
        />
        <Route
          path="/sessions"
          element={
            <ProtectedRoute>
              <ComingSoonPage title="My Sessions" />
            </ProtectedRoute>
          }
        />

        {/* Mentor Routes */}
        <Route
          path="/become-mentor"
          element={
            <ProtectedRoute>
              <ComingSoonPage title="Become a Mentor" />
            </ProtectedRoute>
          }
        />
        <Route
          path="/mentor/dashboard"
          element={
            <ProtectedRoute roles={['mentor', 'admin', 'superadmin']}>
              <ComingSoonPage title="Mentor Dashboard" />
            </ProtectedRoute>
          }
        />

        {/* Admin Routes */}
        <Route
          path="/admin/*"
          element={
            <ProtectedRoute roles={['admin', 'superadmin']}>
              <ComingSoonPage title="Admin Panel" />
            </ProtectedRoute>
          }
        />

        {/* 404 */}
        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </Suspense>
  );
}

export default App;
